  check('head moved up', sn[0].y === 9 && sn[0].x === 10);

  // 4. reverse is ignored (down while heading up)
  S.setDirection(0,1);
  S.tick();
  sn = S.getSnake();
  check('reverse ignored (still up)', sn[0].y === 8 && sn[0].x === 10);

  // 5. wall collision
  S.showReady(); window.__testStartPlay();
