  check('new food not on snake', !S.getSnake().some(s=>s.x===S.getFood().x && s.y===S.getFood().y));

  // 7. self collision
  S.showReady(); window.__testStartPlay();
  const s3 = S.getSnake(); s3[0].x=5;s3[0].y=5; s3[1].x=4;s3[1].y=5; s3[2].x=4;s3[2].y=6; s3[3].x=5;s3[3].y=6; s3[4].x=6;s3[4].y=6;
  S.setDirection(0,-1); S.tick(); // head to (5,4)
  S.setDirection(1,0); S.tick(); // head to (6,4)
  S.setDirection(0,1); S.tick(); // head to (6,5) which is body[4]
  check('self collision ends game', S.getState()==='over');

  results.forEach(r=>console.log(r));
  console.log('SUMMARY: ' + (pass?'ALL PASS':'SOME FAIL'));
  return {pass};
