* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: #111;
  color: #eee;
  font-family: sans-serif;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

#wrap {
  text-align: center;
}

h1 {
  margin-bottom: 8px;
  font-size: 24px;
}

#score {
  margin-bottom: 8px;
  font-size: 16px;
}

#board {
  position: relative;
  width: 600px;
  height: 600px;
  background: #000;
  border: 1px solid #444;
}

canvas {
  display: block;
}

.overlay,
.gameover {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background: rgba(0, 0, 0, 0.75);
  color: #fff;
  font-size: 22px;
  text-align: center;
  gap: 12px;
}

#finalScore {
  font-size: 18px;
}

button {
  font-size: 16px;
  padding: 8px 16px;
  cursor: pointer;
}

.hidden {
  display: none !important;
}

// Ticket 1: Minimal playable snake game.
// Board size fixed at default 20. Snake moves, changes direction via
// arrow keys, eats food to grow/score, wall/self collision ends game.

const BOARD_SIZE = 20;          // number of cells per row/column
const TICK_MS = 150;            // fixed movement interval
const CANVAS_PX = 600;          // canvas is square, in pixels

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const overlay = document.getElementById('overlay');
const overlayText = document.getElementById('overlayText');
const gameover = document.getElementById('gameover');
const finalScoreEl = document.getElementById('finalScore');
const playAgainBtn = document.getElementById('playAgain');

const cell = CANVAS_PX / BOARD_SIZE;

// Game state
let snake, dir, nextDir, food, score, state;
// state: 'ready' (overlay shown) | 'playing' | 'over'

function randCell() {
  return Math.floor(Math.random() * BOARD_SIZE);
}

function randomFood() {
  // Pick a random empty cell (not occupied by the snake).
  let cell;
  do {
    cell = { x: randCell(), y: randCell() };
  } while (snake.some(s => s.x === cell.x && s.y === cell.y));
  return cell;
}

function resetGame() {
  const cx = Math.floor(BOARD_SIZE / 2);
  const cy = Math.floor(BOARD_SIZE / 2);
  // Length 3, heading right. Body laid out along the row to the left.
  snake = [
    { x: cx, y: cy },
    { x: cx - 1, y: cy },
    { x: cx - 2, y: cy },
  ];
  dir = { x: 1, y: 0 };
  nextDir = { x: 1, y: 0 };
  score = 0;
  food = randomFood();
  scoreEl.textContent = 'Score: 0';
}

let tickTimer = 0;
let rafId = 0;

// Begin the "press any key" ready overlay.
function showReady() {
  if (rafId) {
    cancelAnimationFrame(rafId);
    rafId = 0;
  }
  resetGame();
  state = 'ready';
  overlay.classList.remove('hidden');
  gameover.classList.add('hidden');
  draw();
}

// Called on any key while in 'ready' state: start playing.
function startPlaying() {
  if (rafId) {
    cancelAnimationFrame(rafId);
    rafId = 0;
  }
  state = 'playing';
  overlay.classList.add('hidden');
  tickTimer = setInterval(tick, TICK_MS);
  rafId = requestAnimationFrame(loop);
}

function gameOver() {
  state = 'over';
  if (tickTimer) {
    clearInterval(tickTimer);
    tickTimer = 0;
  }
  if (rafId) {
    cancelAnimationFrame(rafId);
    rafId = 0;
  }
  finalScoreEl.textContent = 'Final Score: ' + score;
  gameover.classList.remove('hidden');
}

function setDirection(nx, ny) {
  // Prevent reversing directly into self.
  if (nx === -dir.x && ny === -dir.y) return;
  nextDir = { x: nx, y: ny };
}

function tick() {
  dir = nextDir;
  const head = snake[0];
  const newHead = { x: head.x + dir.x, y: head.y + dir.y };

  // Wall collision.
  if (
    newHead.x < 0 ||
    newHead.y < 0 ||
    newHead.x >= BOARD_SIZE ||
    newHead.y >= BOARD_SIZE
  ) {
    gameOver();
    return;
  }

  // Self collision (check against current body; tail will move unless eating).
  const willEat = newHead.x === food.x && newHead.y === food.y;
  const body = willEat ? snake : snake.slice(0, -1);
  if (body.some(s => s.x === newHead.x && s.y === newHead.y)) {
    gameOver();
    return;
  }

  snake.unshift(newHead);

  if (willEat) {
    score += 1;
    scoreEl.textContent = 'Score: ' + score;
    food = randomFood();
  } else {
    snake.pop();
  }
}

function loop() {
  // Rendering loop; game ticks are driven by setInterval(tick, TICK_MS).
  if (state === 'playing') {
    draw();
  }
  rafId = requestAnimationFrame(loop);
}

function draw() {
  // Background.
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, CANVAS_PX, CANVAS_PX);

  // Food.
  ctx.fillStyle = '#f44';
  ctx.fillRect(food.x * cell, food.y * cell, cell, cell);

  // Snake.
  ctx.fillStyle = '#4f4';
  snake.forEach(s => {
    ctx.fillRect(s.x * cell, s.y * cell, cell, cell);
  });
}

// --- Input ---
window.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'ArrowUp':    case 'w': case 'W': setDirection(0, -1); break;
    case 'ArrowDown':  case 's': case 'S': setDirection(0, 1); break;
    case 'ArrowLeft':  case 'a': case 'A': setDirection(-1, 0); break;
    case 'ArrowRight': case 'd': case 'D': setDirection(1, 0); break;
    default: break;
  }

  if (state === 'ready' && e.key.length === 1) {
    // Any non-modifier single-char key starts play.
    startPlaying();
  }
});

playAgainBtn.addEventListener('click', () => {
  showReady();
});

// Expose state for in-browser verification (removed after testing).
window.__snake = {
  getState: () => state,
  getSnake: () => snake,
  getDir: () => dir,
  getFood: () => food,
  getScore: () => score,
  showReady,
  startPlay: () => startPlaying(),
};

// Initialize.
showReady();

