#!/bin/bash
# Minimal chrome-devtools-axi driver that talks to the running chrome-devtools-mcp
# bridge on port 9224 (avoids the CLI's duplicate-bridge spawn hang).
PORT=9224
call() {
  curl -s --max-time "$2" -X POST "http://127.0.0.1:$PORT/call" \
    -H "Content-Type: application/json" \
    -d "{\"name\":\"$1\",\"args\":$3}"
}
cmd="$1"; shift
case "$cmd" in
  snapshot) call take_snapshot 15 '{}' | sed 's/^{"result":"//; s/\\n$//; s/\\n/\n/g' ;;
  open) call navigate_page 20 "{\"type\":\"url\",\"url\":\"$1\"}" ;;
  newpage) call new_page 20 "{\"url\":\"$1\"}" ;;
  selectpage) call select_page 15 "{\"pageId\":\"$1\"}" ;;
  eval) call evaluate_script 20 "{\"function\":\"$1\"}" | sed 's/^{"result":"//; s/"$//' ;;
  click) call click 20 "{\"uid\":\"$1\"}" ;;
  fill) call fill 20 "{\"uid\":\"$1\",\"value\":\"$2\"}" ;;
  type) call type_text 20 "{\"text\":\"$1\"}" ;;
  press) call press_key 20 "{\"key\":\"$1\"}" ;;
  screenshot) call take_screenshot 20 "{\"filePath\":\"$1\"}" ;;
  resize) call set_window_size 20 "{\"width\":$1,\"height\":$2}" ;;
  wait) call wait_for 30 "{\"text\":[$1]}";;
  *) echo "unknown cmd: $cmd";;
esac

