#!/usr/bin/env python3
import json, sys, urllib.request

PORT = 9224

def call(name, args, function=None):
    body = {"name": name, "args": args}
    if function is not None:
        body["args"] = {"function": function}
    data = json.dumps(body).encode()
    req = urllib.request.Request(
        f"http://127.0.0.1:{PORT}/call",
        data=data,
        headers={"Content-Type": "application/json"},
    )
    with urllib.request.urlopen(req, timeout=20) as resp:
        out = resp.read().decode()
    parsed = json.loads(out)
    result = parsed.get("result", "")
    # chrome-devtools-mcp wraps result in {"result": "..."}
    if isinstance(result, dict):
        return result.get("result", "")
    return result

if __name__ == "__main__":
    cmd = sys.argv[1]
    if cmd == "eval":
        fn = sys.argv[2]
        print(call("evaluate_script", {}, function=fn))
    elif cmd == "click":
        print(call("click", {"uid": sys.argv[2]}))
    elif cmd == "fill":
        print(call("fill", {"uid": sys.argv[2], "value": sys.argv[3]}))
    elif cmd == "press":
        print(call("press_key", {"key": sys.argv[2]}))
    elif cmd == "snapshot":
        print(call("take_snapshot", {}))
    elif cmd == "open":
        print(call("navigate_page", {"type": "url", "url": sys.argv[2]}))
    else:
        print("unknown", cmd)

