// Handle viewport changes: re-size the canvas to fit.
window.addEventListener('resize', () => {
  resizeCanvas();
  if (state === 'menu') draw();
});

// --- Self-test harness (removed after verifying ticket 2) ---
// Exposes internal game functions and state on window so the loop is steppable
// and rules can be asserted with scripted inputs in a real browser.
window.__selfTest = function () {
  const results = [];
  function assert(name, cond) {
    results.push((cond ? 'PASS' : 'FAIL') + ': ' + name);
  }

  // 1. Board size clamping.
  boardSizeInput.value = '5';
  applyBoardSize();
  assert('board size clamped to min 10', boardSize === 10);
  boardSizeInput.value = '500';
  applyBoardSize();
  assert('board size clamped to max 99', boardSize === 99);
  boardSizeInput.value = '20';
  applyBoardSize();
  assert('board size accepts valid 20', boardSize === 20);

  // 2. Cell size never below MIN_CELL_PX.
  boardSizeInput.value = '99';
  applyBoardSize();
  assert('cell >= 12px at max board', cell >= MIN_CELL_PX);
  boardSizeInput.value = '20';
  applyBoardSize();

  // 3. resetGame: snake length 3, heading right, score 0.
  resetGame();
  assert('snake length is 3', snake.length === 3);
  assert('snake heading right', dir.x === 1 && dir.y === 0);
  assert('score starts at 0', score === 0);

  // 4. Food spawns on an empty cell (not on the snake).
  assert('food not on snake', !snake.some(s => s.x === food.x && s.y === food.y));

  // 5. Direction cannot reverse into self.
  dir = { x: 1, y: 0 };
  nextDir = { x: 1, y: 0 };
  setDirection(-1, 0);
  assert('reverse direction ignored', nextDir.x === 1 && nextDir.y === 0);
  setDirection(0, -1);
  assert('valid direction applied', nextDir.x === 0 && nextDir.y === -1);

  // 6. Wall collision ends game.
  resetGame();
  dir = { x: 1, y: 0 };
  nextDir = { x: 1, y: 0 };
  // Force head to a wall.
  snake[0].x = boardSize - 1;
  assert('wall collision triggers game over', (function () {
    gameOverCalled = false;
    const orig = gameOver;
    gameOver = function () { gameOverCalled = true; orig(); };
    tick();
    gameOver = orig;
    return gameOverCalled;
  })());

  // 7. Eating food grows snake, increments score, spawns new food.
  resetGame();
  // Place food adjacent to head.
  const headX = snake[0].x + dir.x;
  const headY = snake[0].y + dir.y;
  food = { x: headX, y: headY };
  const beforeLen = snake.length;
  tick();
  assert('eating grows snake by 1', snake.length === beforeLen + 1);
  assert('eating increments score', score === 1);
  assert('new food not on snake', !snake.some(s => s.x === food.x && s.y === food.y));

  // 8. Self collision ends game.
  resetGame();
  // Build a configuration where the head can run into the body.
  dir = { x: 1, y: 0 };
  nextDir = { x: 1, y: 0 };
  const cx = Math.floor(boardSize / 2);
  const cy = Math.floor(boardSize / 2);
  snake = [
    { x: cx, y: cy }, { x: cx - 1, y: cy }, { x: cx - 2, y: cy },
    { x: cx - 3, y: cy }, { x: cx - 4, y: cy },
  ];
  // Move head right then down then left into body via scripted ticks.
  gameOverCalled = false;
  const orig2 = gameOver;
  gameOver = function () { gameOverCalled = true; orig2(); };
  setDirection(0, 1); tick();        // down
  setDirection(-1, 0); tick();       // left
  setDirection(-1, 0); // keep left
  // Move enough to loop back: drive into the tail row.
  let guard = 0;
  while (!gameoverCalled && guard++ < 60) {
    // steer to collide with body
    const h = snake[0];
    // simple: keep going left until collision
    setDirection(-1, 0);
    tick();
  }
  gameOver = orig2;
  assert('self collision triggers game over', gameOverCalled);

  // 9. Session high score updates on game over and persists in memory.
  resetGame();
  highScore = 0;
  score = 5;
  gameOver();
  assert('high score updates above previous', highScore === 5);
  assert('high score not lowered by lower score', (function () {
    score = 2;
    gameOver();
    return highScore === 5;
  })());

  // Restore a clean menu state.
  boardSizeInput.value = '20';
  applyBoardSize();
  showMenu();

  const failed = results.some(r => r.startsWith('FAIL'));
  console.log('SELF-TEST ' + (failed ? 'FAILURES: ' + results.filter(r => r.startsWith('FAIL')).length : 'ALL PASS (' + results.length + ')'));
  results.forEach(r => console.log('  ' + r));
  return { ok: !failed, results };
};

// Initialize.
state = 'menu';
menu.classList.remove('hidden');
overlay.classList.add('hidden');
gameover.classList.add('hidden');
showMenu();

