const boardSizeInput = document.getElementById('boardSize');
const highScoreEl = document.getElementById('highScore');
const startBtn = document.getElementById('startBtn');
const boardEl = document.getElementById('board');

// Session high score (in-memory; resets on reload).
let highScore = 0;

// Configurable board size. `boardSize` is the number of cells per row/column.
let boardSize = 20;
// Pixel size of the canvas (square). Sized to fit the viewport.
let canvasPx = 600;
// Pixel size of a single cell, derived from canvasPx / boardSize.
let cell = canvasPx / boardSize;

// Game state
let snake, dir, nextDir, food, score, state;
// state: 'menu' | 'ready' (overlay shown) | 'playing' | 'over'

function randCell(n) {
  return Math.floor(Math.random() * n);
}

function randomFood() {
  // Pick a random empty cell (not occupied by the snake).
  let c;
  do {
    c = { x: randCell(boardSize), y: randCell(boardSize) };
  } while (snake.some(s => s.x === c.x && s.y === c.y));
  return c;
}

// Size the canvas to fit the available viewport while respecting the board
// size: each cell must be at least MIN_CELL_PX, and the board must fit the
// smaller viewport dimension minus UI chrome.
function resizeCanvas() {
  // Available square dimension: use the smaller of viewport width/height,
  // leaving room for the title + score + padding (UI chrome).
  const chrome = 180; // title, score, padding
  const avail = Math.min(window.innerWidth, window.innerHeight) - chrome;
  const target = Math.max(MIN_BOARD_SIZE * MIN_CELL_PX, avail);

  // Cap board size so cells stay >= MIN_CELL_PX.
  const maxBoardForCells = Math.floor(avail / MIN_CELL_PX);
  boardSize = Math.max(MIN_BOARD_SIZE, Math.min(MAX_BOARD_SIZE, boardSize));
  boardSize = Math.min(boardSize, maxBoardForCells);
  boardSize = Math.max(MIN_BOARD_SIZE, boardSize);

  boardSizeInput.min = MIN_BOARD_SIZE;
  boardSizeInput.max = MAX_BOARD_SIZE;
  boardSizeInput.value = boardSize;

  canvasPx = Math.round(target);
  canvas.width = canvasPx;
  canvas.height = canvasPx;
  cell = canvasPx / boardSize;
}

function resetGame() {
  const cx = Math.floor(boardSize / 2);
  const cy = Math.floor(boardSize / 2);
  // Length 3, heading right. Body laid out along the row to the left.
  snake = [
    { x: cx, y: cy },
    { x: cx - 1, y: cy },
    { x: cx - 2, y: cy },
  ];
  dir = { x: 1, y: 0 };
  nextDir = { x: 1, y: 0 };
  score = 0;
  food = randomFood();
  scoreEl.textContent = 'Score: 0';
}

let tickTimer = 0;
let rafId = 0;

// Show the start menu and hide the board overlays.
function showMenu() {
  if (rafId) {
    cancelAnimationFrame(rafId);
    rafId = 0;
  }
  if (tickTimer) {
    clearInterval(tickTimer);
    tickTimer = 0;
  }
  state = 'menu';
  menu.classList.remove('hidden');
  overlay.classList.add('hidden');
  gameover.classList.add('hidden');
  resizeCanvas();
  draw();
}

// Begin the "press any key" ready overlay after Start Game is clicked.
function showReady() {
  if (rafId) {
    cancelAnimationFrame(rafId);
    rafId = 0;
  }
  if (tickTimer) {
    clearInterval(tickTimer);
    tickTimer = 0;
  }
  resetGame();
  state = 'ready';
  menu.classList.add('hidden');
  overlay.classList.remove('hidden');
  gameover.classList.add('hidden');
  draw();
}

// Called on any key while in 'ready' state: start playing.
function startPlaying() {
  if (rafId) {
    cancelAnimationFrame(rafId);
    rafId = 0;
  }
  state = 'playing';
  overlay.classList.add('hidden');
  tickTimer = setInterval(tick, TICK_MS);
  rafId = requestAnimationFrame(loop);
}

function gameOver() {
  state = 'over';
  if (tickTimer) {
    clearInterval(tickTimer);
    tickTimer = 0;
  }
  if (rafId) {
    cancelAnimationFrame(rafId);
    rafId = 0;
  }
  // Update session high score.
  if (score > highScore) {
    highScore = score;
    highScoreEl.textContent = highScore;
  }
  finalScoreEl.textContent = 'Final Score: ' + score + '  |  High Score: ' + highScore;
  gameover.classList.remove('hidden');
}

function setDirection(nx, ny) {
  // Prevent reversing directly into self.
  if (nx === -dir.x && ny === -dir.y) return;
  nextDir = { x: nx, y: ny };
}

function tick() {
  dir = nextDir;
  const head = snake[0];
  const newHead = { x: head.x + dir.x, y: head.y + dir.y };

  // Wall collision.
  if (
    newHead.x < 0 ||
    newHead.y < 0 ||
    newHead.x >= boardSize ||
    newHead.y >= boardSize
  ) {
    gameOver();
    return;
  }

  // Self collision (check against current body; tail will move unless eating).
  const willEat = newHead.x === food.x && newHead.y === food.y;
  const body = willEat ? snake : snake.slice(0, -1);
  if (body.some(s => s.x === newHead.x && s.y === newHead.y)) {
    gameOver();
    return;
  }

  snake.unshift(newHead);

  if (willEat) {
    score += 1;
    scoreEl.textContent = 'Score: ' + score;
    food = randomFood();
  } else {
    snake.pop();
  }
}

function loop() {
  // Rendering loop; game ticks are driven by setInterval(tick, TICK_MS).
  if (state === 'playing') {
    draw();
  }
  rafId = requestAnimationFrame(loop);
}

function draw() {
  // Background.
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvasPx, canvasPx);

  // Food.
  ctx.fillStyle = '#f44';
  ctx.fillRect(food.x * cell, food.y * cell, cell, cell);

  // Snake.
  ctx.fillStyle = '#4f4';
  snake.forEach(s => {
    ctx.fillRect(s.x * cell, s.y * cell, cell, cell);
  });
}

// --- Input ---
window.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'ArrowUp':    case 'w': case 'W': setDirection(0, -1); break;
    case 'ArrowDown':  case 's': case 'S': setDirection(0, 1); break;
    case 'ArrowLeft':  case 'a': case 'A': setDirection(-1, 0); break;
    case 'ArrowRight': case 'd': case 'D': setDirection(1, 0); break;
    default: break;
  }

  if (state === 'ready' && e.key.length === 1) {
    // Any non-modifier single-char key starts play.
    startPlaying();
  }
});

// Validate and clamp board size input to the allowed range.
function applyBoardSize() {
  let v = parseInt(boardSizeInput.value, 10);
  if (isNaN(v)) v = boardSize;
  v = Math.max(MIN_BOARD_SIZE, Math.min(MAX_BOARD_SIZE, v));
  boardSize = v;
  boardSizeInput.value = v;
  resizeCanvas();
  if (state === 'menu') draw();
}

boardSizeInput.addEventListener('change', applyBoardSize);

startBtn.addEventListener('click', () => {
  applyBoardSize();
  showReady();
});

playAgainBtn.addEventListener('click', () => {
  showMenu();
});

// Handle viewport changes: re-size the canvas to fit.
window.addEventListener('resize', () => {
  resizeCanvas();
  if (state === 'menu') draw();
});

// --- Self-test harness (removed after verifying ticket 2) ---
// Exposes internal game functions and state on window so the loop is steppable
// and rules can be asserted with scripted inputs in a real browser.
window.__selfTest = function () {
  const results = [];
  function assert(name, cond) {
    results.push((cond ? 'PASS' : 'FAIL') + ': ' + name);
  }

  // 1. Board size clamping: min 10 respected.
  boardSizeInput.value = '5';
  applyBoardSize();
  assert('board size clamped to min 10', boardSize === 10);

  // 2. Board size capped by viewport so cells stay >= MIN_CELL_PX.
  boardSizeInput.value = '999';
  applyBoardSize();
  const maxBoardForCells = Math.floor((Math.min(window.innerWidth, window.innerHeight) - 180) / MIN_CELL_PX);
  assert('board size capped by viewport', boardSize === Math.min(99, maxBoardForCells));
  assert('cell >= 12px at max board', cell >= MIN_CELL_PX);

  // 3. Board size accepts a valid value within range/viewport.
  boardSizeInput.value = '20';
  applyBoardSize();
  assert('board size accepts valid 20', boardSize === 20);

  // 4. resetGame: snake length 3, heading right, score 0.
  resetGame();
  assert('snake length is 3', snake.length === 3);
  assert('snake heading right', dir.x === 1 && dir.y === 0);
  assert('score starts at 0', score === 0);

  // 5. Food spawns on an empty cell (not on the snake).
  assert('food not on snake', !snake.some(s => s.x === food.x && s.y === food.y));

  // 6. Direction cannot reverse into self.
  dir = { x: 1, y: 0 };
  nextDir = { x: 1, y: 0 };
  setDirection(-1, 0);
  assert('reverse direction ignored', nextDir.x === 1 && nextDir.y === 0);
  setDirection(0, -1);
  assert('valid direction applied', nextDir.x === 0 && nextDir.y === -1);

  // 7. Wall collision ends game.
  resetGame();
  dir = { x: 1, y: 0 };
  nextDir = { x: 1, y: 0 };
  // Force head onto the wall.
  snake[0].x = boardSize - 1;
  let wallOver = false;
  const origWall = gameOver;
  gameOver = function () { wallOver = true; origWall(); };
  tick();
  gameOver = origWall;
  assert('wall collision triggers game over', wallOver);

  // 8. Eating food grows snake, increments score, spawns new food.
  resetGame();
  // Place food adjacent to head.
  const headX = snake[0].x + dir.x;
  const headY = snake[0].y + dir.y;
  food = { x: headX, y: headY };
  const beforeLen = snake.length;
  tick();
  assert('eating grows snake by 1', snake.length === beforeLen + 1);
  assert('eating increments score', score === 1);
  assert('new food not on snake', !snake.some(s => s.x === food.x && s.y === food.y));

  // 9. Self collision ends game: drive a length-5 snake in a tight loop.
  resetGame();
  const cx = Math.floor(boardSize / 2);
  const cy = Math.floor(boardSize / 2);
  dir = { x: 1, y: 0 };
  nextDir = { x: 1, y: 0 };
  snake = [
    { x: cx, y: cy }, { x: cx - 1, y: cy }, { x: cx - 2, y: cy },
    { x: cx - 3, y: cy }, { x: cx - 4, y: cy },
  ];
  let selfOver = false;
  const origSelf = gameOver;
  gameOver = function () { selfOver = true; origSelf(); };
  // Right, down, left, up -> head returns toward the body.
  setDirection(0, 1); tick();   // down
  setDirection(-1, 0); tick();  // left
  setDirection(-1, 0); tick();  // left (continue)
  // Keep steering left until it collides with its own body (bounded loop).
  let guard = 0;
  while (!selfOver && guard++ < 120) {
    setDirection(-1, 0);
    tick();
  }
  gameOver = origSelf;
  assert('self collision triggers game over', selfOver);

  // 10. Session high score updates above previous and is not lowered.
  resetGame();
  highScore = 0;
  score = 5;
  gameOver();
  assert('high score updates above previous', highScore === 5);
  score = 2;
  gameOver();
  assert('high score not lowered by lower score', highScore === 5);

  // Restore a clean menu state.
  boardSizeInput.value = '20';
  applyBoardSize();
  showMenu();

  const failed = results.some(r => r.startsWith('FAIL'));
  console.log('SELF-TEST ' + (failed ? 'FAILURES: ' + results.filter(r => r.startsWith('FAIL')).length : 'ALL PASS (' + results.length + ')'));
  results.forEach(r => console.log('  ' + r));
  return { ok: !failed, results };
};

// Initialize.
state = 'menu';
menu.classList.remove('hidden');
overlay.classList.add('hidden');
gameover.classList.add('hidden');
showMenu();

