// --- Self-test harness (removed after verifying ticket 2) ---
// Exposes internal game functions and state on window so the loop is steppable
// and rules can be asserted with scripted inputs in a real browser.
window.__selfTest = function () {
  const results = [];
  function assert(name, cond) {
    results.push((cond ? 'PASS' : 'FAIL') + ': ' + name);
  }

  // 1. Board size clamping: min 10 respected.
  boardSizeInput.value = '5';
  applyBoardSize();
  assert('board size clamped to min 10', boardSize === 10);

  // 2. Board size capped by viewport so cells stay >= MIN_CELL_PX.
  boardSizeInput.value = '999';
  applyBoardSize();
  const maxBoardForCells = Math.floor((Math.min(window.innerWidth, window.innerHeight) - 180) / MIN_CELL_PX);
  assert('board size capped by viewport', boardSize === Math.min(99, maxBoardForCells));
  assert('cell >= 12px at max board', cell >= MIN_CELL_PX);

  // 3. Board size accepts a valid value within range/viewport.
  boardSizeInput.value = '20';
  applyBoardSize();
  assert('board size accepts valid 20', boardSize === 20);

  // 4. resetGame: snake length 3, heading right, score 0.
  resetGame();
  assert('snake length is 3', snake.length === 3);
  assert('snake heading right', dir.x === 1 && dir.y === 0);
  assert('score starts at 0', score === 0);

  // 5. Food spawns on an empty cell (not on the snake).
  assert('food not on snake', !snake.some(s => s.x === food.x && s.y === food.y));

  // 6. Direction cannot reverse into self.
  dir = { x: 1, y: 0 };
  nextDir = { x: 1, y: 0 };
  setDirection(-1, 0);
  assert('reverse direction ignored', nextDir.x === 1 && nextDir.y === 0);
  setDirection(0, -1);
  assert('valid direction applied', nextDir.x === 0 && nextDir.y === -1);

  // 7. Wall collision ends game.
  resetGame();
  dir = { x: 1, y: 0 };
  nextDir = { x: 1, y: 0 };
  // Force head onto the wall.
  snake[0].x = boardSize - 1;
  let wallOver = false;
  const origWall = gameOver;
  gameOver = function () { wallOver = true; origWall(); };
  tick();
  gameOver = origWall;
  assert('wall collision triggers game over', wallOver);

  // 8. Eating food grows snake, increments score, spawns new food.
  resetGame();
  // Place food adjacent to head.
  const headX = snake[0].x + dir.x;
  const headY = snake[0].y + dir.y;
  food = { x: headX, y: headY };
  const beforeLen = snake.length;
  tick();
  assert('eating grows snake by 1', snake.length === beforeLen + 1);
  assert('eating increments score', score === 1);
  assert('new food not on snake', !snake.some(s => s.x === food.x && s.y === food.y));

  // 9. Self collision ends game: drive a length-5 snake in a tight loop.
  resetGame();
  const cx = Math.floor(boardSize / 2);
  const cy = Math.floor(boardSize / 2);
  dir = { x: 1, y: 0 };
  nextDir = { x: 1, y: 0 };
  snake = [
    { x: cx, y: cy }, { x: cx - 1, y: cy }, { x: cx - 2, y: cy },
    { x: cx - 3, y: cy }, { x: cx - 4, y: cy },
  ];
  let selfOver = false;
  const origSelf = gameOver;
  gameOver = function () { selfOver = true; origSelf(); };
  // Right, down, left, up -> head returns toward the body.
  setDirection(0, 1); tick();   // down
  setDirection(-1, 0); tick();  // left
  setDirection(-1, 0); tick();  // left (continue)
  // Keep steering left until it collides with its own body (bounded loop).
  let guard = 0;
  while (!selfOver && guard++ < 120) {
    setDirection(-1, 0);
    tick();
  }
  gameOver = origSelf;
  assert('self collision triggers game over', selfOver);

  // 10. Session high score updates above previous and is not lowered.
  resetGame();
  highScore = 0;
  score = 5;
  gameOver();
  assert('high score updates above previous', highScore === 5);
  score = 2;
  gameOver();
  assert('high score not lowered by lower score', highScore === 5);

  // Restore a clean menu state.
  boardSizeInput.value = '20';
  applyBoardSize();
  showMenu();

  const failed = results.some(r => r.startsWith('FAIL'));
  console.log('SELF-TEST ' + (failed ? 'FAILURES: ' + results.filter(r => r.startsWith('FAIL')).length : 'ALL PASS (' + results.length + ')'));
